    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color and all(grid[y][x] == color
                             for y in range(r, r + 3)
                             for x in range(c, c + 3)):
                centers.append((r + 1, c + 1, color))
    # Extend each object's central row and column. Conflicting rays cancel.
